    public class CheckboxImageConverter : System.Windows.Data.IMultiValueConverter
    {
        public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
        {
            // Check for null or invalid inputs
            if (values.Length != 2 || !(values[0] is bool) || !(values[1] is bool))
            {
                return null;
            }

            bool isMouseOver = (bool)values[0];
            bool isChecked = (bool)values[1];

            // This code gets the directory of your executing .NET assembly.
            // It's a robust way to get the base path regardless of the entry point (gekko.exe).
            string assemblyDir = G.GekkoExeFolder();

            string imagePath;

            if (isMouseOver && !isChecked)
            {
                imagePath = System.IO.Path.Combine(assemblyDir, "images", "hover.png");
            }
            else if (isChecked)
            {
                imagePath = System.IO.Path.Combine(assemblyDir, "images", "checked.png");
            }
            else
            {
                imagePath = Path.Combine(assemblyDir, "images", "normal.png");
            }

            // Return a BitmapImage object with the correct Uri
            return new System.Windows.Media.Imaging.BitmapImage(new Uri(imagePath));
        }

        public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
        {
            throw new NotImplementedException();
        }
    }

    public class Masks
    {

        Dictionary<MultidimElement, MaskPeriods> storage = new Dictionary<MultidimElement, MaskPeriods>();

        public bool Get(MultidimElement mmi, GekkoTime t)
        {
            bool rv = false;
            MaskPeriods p = this.GetPeriods(mmi);
            if (p == null)
            {
                //return false
            }
            else
            {
                int offset = t.Subtract(p.t0);
                if (offset < 0 || offset >= p.ba.Length)
                {
                    //do nothing, keep it false
                }
                else
                {
                    rv = p.ba.Get(offset);
                }
            }
            return rv;
        }

        public void Set(MultidimElement mmi, GekkoTime t)
        {
            int minEnlarge = 32;  //BitArray is internally an int[].
            MaskPeriods p = this.GetPeriods(mmi);

            if (p == null)
            {
                p = new MaskPeriods();
                p.t0 = t;
                p.ba = new BitArray(minEnlarge);
                p.ba.Set(0, true);
                this.storage.Add(mmi, p);
            }
            else
            {
                int offset = t.Subtract(p.t0);
                if (offset < 0)
                {
                    //Must enlarge and move
                    int n1 = p.ba.Length;
                    int enlarge = G.RoundUpToNearest32(p.ba.Length - offset);
                    p.ba = Masks.EnlargeBitArrayLeft(p.ba, enlarge, false);
                    int n2 = p.ba.Length;
                    p.t0 = p.t0.Add(n1 - n2);
                    offset += n2 - n1;
                }
                else if (offset >= p.ba.Length)
                {
                    p.ba.Length = G.RoundUpToNearest32(offset + 1);  //with offset == 32, we then get 64
                }
                p.ba.Set(offset, true);                
            }
        }        

        /// <summary>
        /// Tries to find an array of active periods
        /// </summary>
        /// <param name="mmi"></param>
        /// <returns></returns>
        private MaskPeriods GetPeriods(MultidimElement mmi)
        {
            MaskPeriods p = null; this.storage.TryGetValue(mmi, out p);
            return p;
        }

        public static BitArray EnlargeBitArrayLeft(BitArray original, int newSize, bool fillValue)
        {
            if (newSize <= original.Length) new Error("New size must be larger than the original size.");
            // Create a new BitArray with the desired size
            BitArray newArray = new BitArray(newSize, fillValue);
            // Convert BitArray to bool array for fast copying
            bool[] originalArray = new bool[original.Length];
            original.CopyTo(originalArray, 0);
            bool[] newArrayData = new bool[newSize];
            // Fast block copy to shifted position
            Array.Copy(originalArray, 0, newArrayData, newSize - original.Length, original.Length);
            // Convert back to BitArray
            return new BitArray(newArrayData);
        }       
    }

    public class MaskPeriods 
    {
        public GekkoTime t0 = GekkoTime.tNull;
        public BitArray ba = null;

        public string ToString()
        {
            string s = null;
            for (int i = 0; i < this.ba.Length; i++)
            {
                if (this.ba[i]) s += (t0.Add(i)).ToString() + " ";
            }
            return s;
        }
    }

