        public ParallelHelper() //just for protobuf
        {
        }

        public ParallelHelper(string name, IVariable iv)
        {
            this.name = name;
            this.iv = iv;
        }

        public ParallelHelper(Trace2 trace)
        {
            this.trace = trace;
        }

        public bool IsTrace()
        {
            return this.trace != null;
        }
    }

