        /// <summary>
        /// Can handle lag in input, and always returns a DName with lag/lead. 
        /// Hacky, try to get rid of it when scalar model dicts are done. 
        /// Can translate x, x[-1], x[a][-1] into proper DName with lag.
        /// </summary>
        /// <param name="s"></param>
        /// <returns></returns>
        public static DName DName_HACK1LAG(string s)
        {
            string bank = null; string name = null; string freq = null; string[] indexes1 = null; string[] indexes2 = null;
            G.Chop_Chop_Jagged(s, out bank, out name, out freq, out indexes1, out indexes2);

            if (indexes1 == null && indexes2 == null)
            {
                // x
                return new DNameLag(name, G.ConvertFreq(freq), new StringOrTime[] { new GekkoTime(EFreq.Lag, 0) }, -1);
            }
            else if (indexes1 != null && indexes2 == null)
            {
                // x[-1], x[+1], x[a], x[i,j]
                if (indexes1.Length == 1)
                {
                    // x[-1], x[+1]
                    int i; if (!int.TryParse(indexes1[0], out i)) i = -12345;
                    if (i != -12345) return new DName(name, G.ConvertFreq(freq), new StringOrTime[] { new GekkoTime(EFreq.Lag, i) }, -1);
                }
                // x[a], x[i,j]
                List<StringOrTime> m = new List<StringOrTime>();
                foreach (string s2 in indexes1) m.Add(s2);
                m.Add(new GekkoTime(EFreq.Lag, 0));
                return new DNameLag(name, G.ConvertFreq(freq), m.ToArray(), -1);
            }
            else if (indexes1 != null && indexes2 != null)
            {
                // x[a][-1], x[a][+1], x[i,j][-1], x[i,j][+1]
                if (indexes2.Length != 1) new Error("Bad x[...][...] pattern");
                int i; if (!int.TryParse(indexes2[0], out i)) i = -12345;
                if (i == -12345) new Error("Bad x[...][...] pattern");
                List<StringOrTime> m = new List<StringOrTime>();
                foreach (string s2 in indexes1) m.Add(s2);
                m.Add(new GekkoTime(EFreq.Lag, i));
                return new DNameLag(name, G.ConvertFreq(freq), m.ToArray(), -1);
            }
            else new Error("Hov");
            return null; //we never get here            
        }

        /// <summary>
        /// Hacky. Only removes if it is a lag that appears like a normal dimensions as say string "-1".
        /// Also removes a lead with plus, like "+1".
        /// </summary>
        /// <param name="s1"></param>
        /// <returns></returns>
        public static DName DName_HACK1NOLAG(string s1)
        {            
            string s2 = s1.Replace("][", ",").Replace("] [", ","); //From x[a,b][-1] to x[a,b,-1].

            DName dname = Program.DName_HACK1(s2);

            bool b = false;
            StringOrTime[] xx = dname.GetIndexesExceptTime();
            if (xx != null && xx.Length > 0)
            {
                if (xx[xx.Length - 1].IsString())
                {
                    string s = xx[xx.Length - 1].GetString();
                    int i = -12345; int.TryParse(s, out i);
                    if (i != -12345)
                    {
                        if (i < 0) b = true;
                        else if (i > 0 && s.StartsWith("+")) b = true; //So x[0] or x[18] will not count
                    }
                }
            }
            DName dname2 = dname;
            if (b) dname2 = dname.RemoveLastIndex();
            return dname2;
        }

