        public static void WriteParallelModel(int k, string inputFileName, string hash, double hashMs, Model model)
        {
            DateTime t = DateTime.Now;

            try
            {
                if (Program.model?.modelGekko?.modelInfo != null)
                {
                    PutListsIntoModelListHelper(); //makes Program.model.modelGekko.modelInfo.modelListHelper object
                    string filePath = Path.Combine(Program.options.folder_working, Globals.modelFileName.Replace(".frm", "") + "__info.zip");
                    byte[] data = File.ReadAllBytes(filePath);
                    Program.model.modelGekko.modelInfo.modelListHelper.model__info = data;
                }
            }
            catch { };  //does not fail

            bool print = false; if (Globals.runningOnTTComputer) print = true;
            //Note: k+1 because the first list[0] object is very tiny
            string salt = G.Subperiods(model.modelCommon.GetFreq()).ToString();
            List<string> files = GetSplitCacheFileNames(k + Globals.systemTthreadsExtra + 1, inputFileName, "model", salt, ref hash);  //1 because 1-based, 2 for modelGams and modelGekko
            List<object> lists = ProtobufModelGamsScalar5a(k, model);

            try
            {
                lists.AsParallel().WithExecutionMode(ParallelExecutionMode.ForceParallelism).Select((x, i) =>
                {
                    try
                    {
                        if (File.Exists(files[i])) File.Delete(files[i]);
                    }
                    catch (Exception e)
                    {
                        new Error("Protobuf cache problem (protobuffers). Message: " + e.Message);
                    }
                    try
                    {
                        ProtobufWrite(x, files[i]);
                    }
                    catch (Exception e)
                    {
                        throw;
                    }
                    return true;
                }).All(_ => _);
            }
            catch (Exception e)
            {
                throw;
            }
            finally
            {
                //makes sure stuff is always reverted into model in slot m[0], even if protobuf write fails.
                ProtobufModelGamsScalar5b(Program.options.system_threads, lists);
            }

            List<string> sfiles = new List<string>();
            foreach (string file in files)
            {
                sfiles.Add(G.UpdprtFormat((double)(new FileInfo(file)).Length / 1e6d, 0, false));
            }
            if (print) new Writeln("TTH: Sizes (MB): " + Stringlist.GetListWithCommas(sfiles));

            double milliseconds = (DateTime.Now - t).TotalMilliseconds;
            milliseconds += hashMs;  //else it seems too easy: ReadParallel has already computed MD5
            string s = G.SecondsFormat(milliseconds);
            if (print) new Writeln("TTH: WriteParallelModel: " + s);
        }

        /// <summary>
        /// From the lists Global:#all, Global:#endo etc. we make modelGekko.modelInfo.modelListHelper.* .
        /// NOT USED??
        /// </summary>
        public static void PutListsIntoModelListHelper()
        {

            ModelListHelper modelListHelper = new ModelListHelper();

            if (Program.databanks.GetGlobal().ContainsIVariable(Globals.symbolCollection + "all")) modelListHelper.all = Stringlist.GetListOfStringsFromList(Program.databanks.GetGlobal().GetIVariable(Globals.symbolCollection + "all"));
            if (Program.databanks.GetGlobal().ContainsIVariable(Globals.symbolCollection + "endo")) modelListHelper.endo = Stringlist.GetListOfStringsFromList(Program.databanks.GetGlobal().GetIVariable(Globals.symbolCollection + "endo"));
            if (Program.databanks.GetGlobal().ContainsIVariable(Globals.symbolCollection + "exo")) modelListHelper.exo = Stringlist.GetListOfStringsFromList(Program.databanks.GetGlobal().GetIVariable(Globals.symbolCollection + "exo"));
            if (Program.databanks.GetGlobal().ContainsIVariable(Globals.symbolCollection + "exod")) modelListHelper.exod = Stringlist.GetListOfStringsFromList(Program.databanks.GetGlobal().GetIVariable(Globals.symbolCollection + "exod"));
            if (Program.databanks.GetGlobal().ContainsIVariable(Globals.symbolCollection + "exodjz")) modelListHelper.exodjz = Stringlist.GetListOfStringsFromList(Program.databanks.GetGlobal().GetIVariable(Globals.symbolCollection + "exodjz"));
            if (Program.databanks.GetGlobal().ContainsIVariable(Globals.symbolCollection + "exoj")) modelListHelper.exoj = Stringlist.GetListOfStringsFromList(Program.databanks.GetGlobal().GetIVariable(Globals.symbolCollection + "exoj"));
            if (Program.databanks.GetGlobal().ContainsIVariable(Globals.symbolCollection + "exotrue")) modelListHelper.exotrue = Stringlist.GetListOfStringsFromList(Program.databanks.GetGlobal().GetIVariable(Globals.symbolCollection + "exotrue"));
            if (Program.databanks.GetGlobal().ContainsIVariable(Globals.symbolCollection + "exoz")) modelListHelper.exoz = Stringlist.GetListOfStringsFromList(Program.databanks.GetGlobal().GetIVariable(Globals.symbolCollection + "exoz"));

            Program.model.modelGekko.modelInfo.modelListHelper = modelListHelper;
        }

        /// <summary>
        /// Reads model protobuf files in parallel. Will return null if there is nothing found in cache.
        /// </summary>
        public static Model ReadParallelModelMaybe(string hash)
        {
            bool print = false;
            if (Globals.runningOnTTComputer) print = true;
            DateTime t = DateTime.Now;

            List<string> files = new List<string>();
            List<object> lists = new List<object>();

            string part2 = Globals.gekkoVersion + "_" + "model" + "_" + hash + "_";
            int k = ValidateFileNames(part2);
            if (k == -12345) return null;  //could not find anything useful in cache

            for (int i = 0; i < k; i++)
            {
                files.Add(Globals.localTempFilesLocation + "\\" + Globals.gekkoVersion + "_" + "model" + "_" + hash + "_" + (i + 1) + "of" + k + Globals.cacheExtension);
                lists.Add(new ModelGamsScalar(null));
            }

            //if (print) new Writeln("Serialize (" + k + "): " + G.Seconds(t) + "      hashtime: " + hashTime);
            t = DateTime.Now;

            if (true)
            {
                Parallel.ForEach(lists, () => 0, (x, pls, index, s) =>
                {
                    //See https://github.com/protobuf-net/protobuf-net/issues/668
                    //About double speed on TT pc, compared to no parallel  
                    int i = (int)index;
                    object o = null;
                    if (new FileInfo(files[i]).Length == 0)
                    {
                        //happens when the slot is occupied with a ModelNull() object, which has zero contents.
                        o = new ModelNull();
                    }
                    else
                    {
                        if (i <= Program.options.system_threads) o = ProtobufRead<ModelGamsScalar>(files[i]);
                        else if (i == Program.options.system_threads + 1) o = ProtobufRead<ModelCommon>(files[i]);
                        else if (i == Program.options.system_threads + 2) o = ProtobufRead<ModelGams>(files[i]);
                        else if (i == Program.options.system_threads + 3) o = ProtobufRead<ModelGekko>(files[i]);
                    }
                    lists[i] = o;
                    return 0;
                }, _ => { });
            }

            Model model = ProtobufModelGamsScalar5b(Program.options.system_threads, lists);

            if (model.modelGekko != null)
            {
                //get lists #endo, #exo, #exotrue, etc. (8 in all, into Global).
                GetListsFromModelListHelper(model.modelGekko);
                //=============================================
                //FOR SAFETY: see mail from TKD 5/3 2013
                model.modelGekko.simulateResults = new double[10];
                //=============================================   

                try
                {
                    if (model.modelGekko?.modelInfo?.modelListHelper?.model__info != null && model.modelGekko.modelInfo.modelListHelper.model__info.Length > 0)
                    {
                        string filePath2 = Path.Combine(Program.options.folder_working, Globals.modelFileName.Replace(".frm", "") + "__info.zip");
                        if (File.Exists(filePath2)) WaitForFileDelete(filePath2);
                        using (BinaryWriter writer = new BinaryWriter(File.OpenWrite(filePath2)))
                        {
                            writer.Write(model.modelGekko.modelInfo.modelListHelper.model__info);
                        }
                    }
                }
                catch { };  //does not fail

                model.modelGekko.modelInfo.modelListHelper = null;  //only used for temporary transfer of these lists

            }

            return model;
        }

        public static void WriteParallelDatabank(int k, Databank databank, string fileName, string hash, double hashMs, ReadInfo readInfo)
        {
            try
            {
                int extra = 1;

                DateTime t = DateTime.Now;
                bool print = false; if (Globals.runningOnTTComputer) print = true;

                List<string> files = GetSplitCacheFileNames(k + extra, fileName, "data", null, ref hash); //the last filename is cache parameters

                List<List<ParallelHelper>> lists = new List<List<ParallelHelper>>();
                List<TwoInts> twoIntss = new List<TwoInts>();
                for (int i = 0; i < k; i++)
                {
                    lists.Add(new List<ParallelHelper>());
                    twoIntss.Add(new TwoInts(int.MaxValue, int.MinValue));
                }

                TraceHelper th; Dictionary<TraceID2, Trace2> dict1Inverted;
                Gekko.Trace2.HandleTraceWrite(databank, out th, out dict1Inverted);

                lists = SplitVarsInSameSizeParts(databank.storage, k, print);

                int n = 0;
                while (true)
                {
                    for (int i = 0; i < k; i++)
                    {
                        if (n >= databank.traces.Count) goto Lbl;
                        lists[i].Add(new ParallelHelper(databank.traces[n]));
                        n++;
                    }
                }
            Lbl:;


                foreach (List<ParallelHelper> x1 in lists)
                {
                    foreach (ParallelHelper x2 in x1)
                    {
                        if (!x2.IsTrace())
                        {
                            Program.ProtobufWalker(x2.iv, true);
                        }
                    }
                }

                lists.AsParallel().WithExecutionMode(ParallelExecutionMode.ForceParallelism).Select((x, i) =>
                {
                    try
                    {
                        if (File.Exists(files[i])) File.Delete(files[i]);
                    }
                    catch (Exception e)
                    {
                        new Error("Protobuf cache problem (protobuffers). Message: " + e.Message);
                    }
                    ProtobufWrite(x, files[i]);
                    return true;
                }).All(_ => _);

                //write out the cache parameters object
                //read cache parameters
                //TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO 
                //TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO 
                // ------> if databank.traces is big, it should be written in parallel together with the others! See also #kgs6dskdfs
                //TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO 
                //TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO 
                DateTime dt0 = DateTime.Now;
                ProtobufWrite(databank.cacheParameters, files[k + extra - 1]);
                if (Globals.runningOnTTComputer) new Writeln("TTH: Write time cache params: " + G.Seconds(dt0));
                dt0 = DateTime.Now;
                Gekko.Trace2.HandleTraceRead2(th.metas, dict1Inverted);

                List<string> sfiles = new List<string>();
                foreach (string file in files)
                {
                    sfiles.Add(G.UpdprtFormat((double)(new FileInfo(file)).Length / 1e6d, 0, false));
                }
                if (print) new Writeln("TTH: Sizes (MB): " + Stringlist.GetListWithCommas(sfiles));
                double milliseconds = (DateTime.Now - t).TotalMilliseconds;
                milliseconds += hashMs;  //else it seems too easy: ReadParallel has already computed MD5
                string s = G.SecondsFormat(milliseconds);
                readInfo.note += "Cache write time: " + s + ". ";
            }
            finally
            {
                if (databank != null) databank.traces = null;  //important!
            }
        }

        /// <summary>
        /// Makes k files with names [hash]...1of5, ...2of5, etc. If hash==null, it will be calculated and returned.
        /// Type is "data" or "model". If something containg the hash name is present, these files are deleted first.
        /// 
        /// </summary>
        /// <param name="k"></param>
        /// <param name="inputFileNameUsedForHash"></param>
        /// <param name="type"></param>
        /// <param name="hash"></param>
        /// <returns></returns>
        private static List<string> GetSplitCacheFileNames(int k, string inputFileNameUsedForHash, string type, string salt, ref string hash)
        {
            if (hash == null)
            {
                //never happens? When an unseen file is encountered, ReadParallel will have computed the hash to see if it is known.
                //so this is just for double safety.
                hash = Program.GetMD5Hash(null, inputFileNameUsedForHash, salt, null);
            }

            List<string> files = new List<string>();

            string part2 = Globals.gekkoVersion + "_" + type + "_" + hash + "_";
            string[] hits = Directory.GetFiles(Globals.localTempFilesLocation, part2 + "*" + Globals.cacheExtension);
            foreach (string hit in hits)
            {
                //Clean sheet for this hash
                File.Delete(hit);
            }

            for (int i = 0; i < k; i++)
            {
                files.Add(Globals.localTempFilesLocation + "\\" + part2 + (i + 1) + "of" + k + Globals.cacheExtension);
            }

            return files;
        }

        public static Databank ReadParallelDatabank(string fileName, out int year1, out int year2, out string hash, out double hashMs, ReadInfo readInfo)
        {
            // Test of read of large calib.gdx (176 MB) with different number of splitfiles.
            //
            // 1    6.40
            // 2    4.30
            // 3    3.90
            // 4    3.70
            // 5    3.70
            // ... after this about the same
            //
            // Perhaps with many splitfiles, the lower bound is 3.70 s, but with larger variability.
            // Seems that split = 3 at least. Perhaps the processors+1 rule is ok, therefore 5?
            //
            // When we have a 1of1, just read it without parallel.foreach (same for write).

            Databank databank = null;

            try
            {

                int extra = 1;

                bool print = false;
                if (Globals.runningOnTTComputer) print = true;

                year1 = int.MaxValue;
                year2 = int.MinValue;
                DateTime t = DateTime.Now;
                hash = Program.GetMD5Hash(null, fileName, null, null);
                hashMs = (DateTime.Now - t).TotalMilliseconds;

                List<string> files = new List<string>();
                List<List<ParallelHelper>> lists = new List<List<ParallelHelper>>();
                List<TwoInts> twoIntss = new List<TwoInts>();

                string part2 = Globals.gekkoVersion + "_" + "data" + "_" + hash + "_";
                int k = ValidateFileNames(part2);
                if (k == -12345) return null;  //could not find anything useful in cache

                for (int i = 0; i < k; i++)
                {
                    files.Add(Globals.localTempFilesLocation + "\\" + Globals.gekkoVersion + "_" + "data" + "_" + hash + "_" + (i + 1) + "of" + k + Globals.cacheExtension);
                }

                for (int i = 0; i < k - extra; i++)
                {
                    lists.Add(new List<ParallelHelper>());
                    twoIntss.Add(new TwoInts(int.MaxValue, int.MinValue));
                }

                t = DateTime.Now;

                Parallel.ForEach(lists, () => 0, (x, pls, index, s) =>
                {
                    //See https://github.com/protobuf-net/protobuf-net/issues/668
                    //About double speed on TT pc, compared to no parallel  

                    int i = (int)index;
                    List<ParallelHelper> o = ProtobufRead<List<ParallelHelper>>(files[i]);
                    lists[i] = o;
                    TwoInts yearMinMax = twoIntss[i];
                    foreach (ParallelHelper ph in lists[i])
                    {
                        if (!ph.IsTrace()) ph.iv.DeepCleanup(yearMinMax);  //fixes maps and lists with 0 elements, also binds MultiDim.parent                            
                    }
                    return 0;
                }, _ => { });

                databank = new Databank("temporary");

                DateTime t2 = DateTime.Now;
                databank.traces = new List<Trace2>();
                foreach (List<ParallelHelper> list in lists)
                {
                    foreach (ParallelHelper ph in list)
                    {
                        if (ph.IsTrace())
                        {
                            databank.traces.Add(ph.trace);
                        }
                        else
                        {
                            Program.ProtobufWalker(ph.iv, false);
                            databank.storage.Add(ph.name, ph.iv);
                        }
                    }
                }
                lists = null;  //free for GC            

                for (int i = 0; i < twoIntss.Count; i++)
                {
                    if (twoIntss[i].int1 < year1) year1 = twoIntss[i].int1;
                    if (twoIntss[i].int2 > year2) year2 = twoIntss[i].int2;
                }

                //read cache parameters
                //TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO 
                //TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO 
                // ------> if databank.traces is big, it should be read in parallel together with the others! See also #kgs6dskdfs
                //TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO 
                //TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO TODO 
                DateTime dt0 = DateTime.Now;
                databank.cacheParameters = ProtobufRead<DatabankCacheParams>(files[k - extra]);
                if (Globals.runningOnTTComputer) new Writeln("TTH: Read time cache params: " + G.Seconds(dt0));
                dt0 = DateTime.Now;
                Gekko.Trace2.HandleTraceRead1(databank);
                if (Globals.runningOnTTComputer) new Writeln("TTH: Handle time traces: " + G.Seconds(dt0));

                //if (print) new Writeln("TTH: Deserialize (" + k + "): " + G.Seconds(t) + "     cleanup: " + G.Seconds(t2));
                readInfo.note += "Cache read time: " + G.Seconds(t) + ". ";

            }
            finally
            {
                if (databank != null) databank.traces = null;  //important!
            }

            return databank;
        }

        public static T ProtobufRead<T>(string fileName2)
        {
            T o;
            using (FileStream fs = WaitForFileStream(fileName2, null, GekkoFileReadOrWrite.Read))
            {
                RuntimeTypeModel serializer = RuntimeTypeModel.Create();
                try
                {
                    o = Serializer.Deserialize<T>(fs);
                }
                catch (Exception e)
                {
                    G.Warning("w32.1", "Technical problem while reading protobuffer file '" + fileName2 + "'. Message: " + e.Message);
                    throw;
                }
            }
            return o;
        }

        private static int ValidateFileNames(string part2)
        {
            string[] hits = Directory.GetFiles(Globals.localTempFilesLocation, part2 + "*" + Globals.cacheExtension);
            int k = ValidateFileNames2(part2, hits);
            if (k == -12345)
            {
                //clean up
                foreach (string hit in hits)
                {
                    File.Delete(hit);
                }
            }
            return k;
        }

        private static int ValidateFileNames2(string part2, string[] hits)
        {
            int i2 = -12345;
            try
            {
                string s = hits[0].Replace(Globals.localTempFilesLocation + "\\" + part2, "").Replace(Globals.cacheExtension, "").Trim();
                int idx = s.IndexOf("of");
                string s2 = s.Substring("of".Length + idx);
                i2 = int.Parse(s2);
            }
            catch
            {
                return -12345;
            }
            if (i2 <= 0) return -12345;
            if (i2 != hits.Length) return -12345;

            for (int i = 0; i < i2; i++)
            {
                if (!hits.Contains(Globals.localTempFilesLocation + "\\" + part2 + (i + 1) + "of" + i2 + Globals.cacheExtension)) return -12345;
            }
            return i2;  //is -12345 if something is wrong
        }

        /// <summary>
        /// We have to recurse/walk here, because [ProtoBeforeSerialization] and
        /// [ProtoAfterDeserialization] do not work inside an object tree structure,
        /// but only at the uppermost object. Before, this was put in Matrix.cs only.
        /// </summary>
        /// <param name="iv"></param>
        /// <param name="isBeforeProtobuf"></param>
        public static void ProtobufWalker(IVariable iv, bool isBeforeProtobuf)
        {
            if (iv.Type() == EVariableType.Matrix)
            {
                Matrix m = (Matrix)iv;
                if (isBeforeProtobuf)
                {
                    m.BeforeProtobufWrite();
                }
                else
                {
                    m.AfterProtobufRead();
                }
            }
            else if (iv.Type() == EVariableType.List)
            {
                List thisList = (List)iv;
                foreach (IVariable iv2 in thisList.list)
                {
                    ProtobufWalker(iv2, isBeforeProtobuf);
                }
            }
            else if (iv.Type() == EVariableType.Map)
            {
                Map thisMap = (Map)iv;
                foreach (KeyValuePair<string, IVariable> kvp in thisMap.storage)
                {
                    ProtobufWalker(kvp.Value, isBeforeProtobuf);
                }
            }
        }

