        /// <summary>
        /// Reads the HEAD file in the .git directory to determine the current branch name. Does not handle worktrees!!
        /// Returns '...' for branch, 'tag: ...' for tag, or 'hash: ...' for commit. Example: 'main' for main branch.
        /// Returns null if nothing is found.
        public static Tuple<string, string> GetCurrentSnapshot(string path)
        {
            string gitMetadataPath = Path.Combine(path, ".git");

            if (string.IsNullOrEmpty(gitMetadataPath) || !Directory.Exists(gitMetadataPath))
            {
                return new Tuple<string, string>(null, null);
            }

            string headFilePath = Path.Combine(gitMetadataPath, "HEAD");

            if (!File.Exists(headFilePath))
            {
                return new Tuple<string, string>(null, null);
            }

            try
            {
                string headContent = File.ReadAllText(headFilePath).Trim();
                string commitHash = null;
                string branchOrState = null;

                // 1. Check for a tracked branch (Attached HEAD: e.g., "ref: refs/heads/main")
                var branchMatch = Regex.Match(headContent, @"^ref:\s*(?<refpath>refs/heads/(?<branchname>.+))$");

                if (branchMatch.Success)
                {
                    // Attached HEAD: Get the branch name and the path to the file containing the hash
                    string refPath = branchMatch.Groups["refpath"].Value;
                    branchOrState = branchMatch.Groups["branchname"].Value;

                    string refFilePath = Path.Combine(gitMetadataPath, refPath);

                    // Read the file containing the actual hash
                    if (File.Exists(refFilePath))
                    {
                        commitHash = File.ReadAllText(refFilePath).Trim();
                    }
                }
                else
                {
                    // 2. Detached HEAD (e.g., a direct 40-character SHA-1 hash)
                    if (Regex.IsMatch(headContent, @"^[0-9a-fA-F]{40}$"))
                    {
                        branchOrState = "DETACHED_HEAD";
                        commitHash = headContent;
                    }
                    // 3. Check for a tag reference (e.g., "ref: refs/tags/v1.0.0")
                    else if (Regex.IsMatch(headContent, @"^ref:\s*(?<refpath>refs/tags/(?<tagname>.+))$"))
                    {
                        var tagMatch = Regex.Match(headContent, @"^ref:\s*(?<refpath>refs/tags/(?<tagname>.+))$");
                        string refPath = tagMatch.Groups["refpath"].Value;
                        branchOrState = $"TAG: {tagMatch.Groups["tagname"].Value}";

                        string refFilePath = Path.Combine(gitMetadataPath, refPath);
                        if (File.Exists(refFilePath))
                        {
                            // Note: For simplicity, we assume lightweight tag or annotated tag reference hash.
                            commitHash = File.ReadAllText(refFilePath).Trim();
                        }
                    }
                    else
                    {
                        branchOrState = "UNKNOWN_STATE";
                    }
                }

                // Return the final tuple
                return new Tuple<string, string>(branchOrState, commitHash);
            }
            catch (Exception)
            {
                // Return a tuple indicating a read error
                return new Tuple<string, string>("READ_ERROR", null);
            }
        }



        /// <summary>
        /// Helper method for the up/down fields in DECOMP and FLOW windows.
        /// </summary>
        /// <param name="s"></param>
        /// <param name="i"></param>
        /// <param name="b"></param>
        public static void GuiHandleNum(string s, out int i, out bool b)
        {
            i = 0;
            b = false;
            if (s == null || s == "")
            {
                b = true;
                i = 0;
            }
            else
            {
                if (s.StartsWith("00"))
                {
                    //do not accept, b will be = false
                }
                else
                {
                    b = int.TryParse(s, out i);
                }
            }
        }


        /// <summary>
        /// For a given input series x (can be array-series), a list of normal series or subseries names is returned,
        /// where the names are found inside the traces of x. Does not return null, but can return empty collection.
        /// </summary>
        /// <param name="ts"></param>
        /// <returns></returns>
        public static GekkoDictionary<string, bool> TraceGetPrecedents(IVariable ivName, string bankname, int direct, TraceBankHelpler helper)
        {
            GekkoDictionary<string, bool> found = new GekkoDictionary<string, bool>(StringComparer.OrdinalIgnoreCase);

            if (ivName == null)
            {
                foreach (KeyValuePair<string, IVariable> kvp in Program.databanks.GetFirst().storage)
                {
                    //will include array-series, which is ok here -- we look at all of them
                    if (kvp.Value.Type() != EVariableType.Series) continue;
                    Series ts = kvp.Value as Series;
                    if (G.Equal(ts.name, "qbnp!a"))
                    {
                    }
                    TraceHelper th1 = new TraceHelper();
                    th1.type = ETraceHelper.GetAllMetasAndTraces;
                    if (direct == 1) th1.depthLimit = 1;
                    else if (direct == 2)
                    {
                        th1.depthLimit = 1;
                        th1.specialAdamStuff = true;
                    }
                    ts.DeepTrace(th1);
                    foreach (Trace2 trace in th1.traces.Keys)
                    {
                        TraceGetPrecedentsHelper(trace, bankname, found, helper);
                    }                    
                }
            }
            else
            {
                Series ts = null;
                if (ivName.Type() == EVariableType.String)
                {
                    ts = O.GetIVariableFromString(O.ConvertToString(ivName), O.ECreatePossibilities.NoneReportError) as Series;
                }
                else if (ivName.Type() == EVariableType.Series)
                {
                    ts = ivName as Series;
                }
                else new Error("Expected the first argument to be of string or series type");

                if (ts == null) new Error("Expected input name to be a series name");
                TraceHelper th1 = new TraceHelper();
                th1.type = ETraceHelper.GetAllMetasAndTraces;
                if (direct == 1) th1.depthLimit = 1;
                else if (direct == 2)
                {
                    th1.depthLimit = 1;
                    th1.specialAdamStuff = true;
                }
                ts.DeepTrace(th1);
                foreach (Trace2 trace in th1.traces.Keys)
                {
                    TraceGetPrecedentsHelper(trace, bankname, found, helper);
                }
            }

            return found;
        }

        /// <summary>
        /// For a trace, it adds to the found list all names in precedentsNames that contains the bankname as databank.
        /// </summary>
        /// <param name="trace"></param>
        /// <param name="bankname"></param>
        /// <param name="found"></param>
        private static void TraceGetPrecedentsHelper(Trace2 trace, string bankname, GekkoDictionary<string, bool> found, TraceBankHelpler helper)
        {
            List<string> precedentsNames = trace.traceContents.precedentsNames;
            if (precedentsNames != null)
            {                
                List<string> names = new List<string>();
                if (helper != null)
                {
                    foreach (string pname in precedentsNames)
                    {
                        string aname = TraceGetPrecedentsHelper2(bankname, pname);
                        if (aname != null)
                        {
                            names.Add(G.Chop_AddBank(G.Chop_RemoveFreq(aname), bankname));
                        }
                    }
                }

                if (helper != null && names.Count > 0)
                {
                    TraceBankHelpler2 tb = new TraceBankHelpler2();
                    tb.makroName = G.Chop_RemoveBank(G.Chop_RemoveFreq(trace.traceContents.name));
                    tb.adamNames = Stringlist.GetListWithCommas(names);
                    tb.period = trace.traceContents.period.t1 + "-" + trace.traceContents.period.t2;
                    tb.code = trace.traceContents.text;
                    //s1 = this.GetContents().text;
                    //string period = this.GetContents().period.t1 + "-" + this.GetContents().period.t2;
                    //int len = "---".Length;
                    //if (s1 != null) len = s1.Length;
                    //s2 += G.Blanks(50 - len - 2 * d) + " --> period: " + period;
                    ////s2 += ", stamp: " + this.GetId().stamp.ToString("g", System.Globalization.CultureInfo.CreateSpecificCulture(Globals.languageDaDK));  //This is SLOOW!
                    //s2 += ", stamp: " + this.GetId().StampInLocalTime().ToString("g", System.Globalization.CultureInfo.GetCultureInfo(Globals.languageDaDK));

                    if (G.Equal(G.Chop_GetName(tb.makroName), "adam2") || G.Equal(G.Chop_GetName(tb.makroName), "adam_io"))
                    {
                        //skip
                    }
                    else
                    {                        
                        helper.elements.Add(tb);                        
                    }
                }
                else
                {
                    foreach (string pname in precedentsNames)
                    {
                        string aname = TraceGetPrecedentsHelper2(bankname, pname);
                        if (aname != null && !found.ContainsKey(aname))
                        {
                            found.Add(aname, false);
                        }
                    }
                }
            }
        }

        /// <summary>
        /// For a variable name like "3¤adambk:x!a", it returns "x" if the bank is correct (== bankname). Can return null.
        /// </summary>
        /// <param name="bankname"></param>
        /// <param name="pname"></param>
        /// <returns></returns>
        private static string TraceGetPrecedentsHelper2(string bankname, string pname)
        {
            string s = pname.Split('¤')[1];
            string bank = G.Chop_GetBank(s);
            string aname = null;
            if (G.Equal(bank, bankname))
            {
                aname = G.Chop_RemoveBank(s); //TODO: could be faster, but is inside an IF, so oh well...                        
            }
            return aname;
        }

        /// <summary>
        /// For a given input series x (can be array-series), a list of normal series or subseries names is returned,
        /// where the names are found inside the traces of x.
        /// </summary>
        /// <param name="ts"></param>
        /// <returns></returns>
        public static GekkoDictionary<string, bool> TraceGetDependents(IVariable ivName, string bankname, int direct)
        {
            GekkoDictionary<string, bool> found = new GekkoDictionary<string, bool>(StringComparer.OrdinalIgnoreCase);            

            if (ivName == null)
            {

                GekkoDictionary<string, IVariable> flat = Program.databanks.GetFirst().StorageFlattenedArrayTimeseries();
                foreach (KeyValuePair<string, IVariable> kvp in flat)
                {
                    if (kvp.Value.Type() != EVariableType.Series) continue;
                    Series ts = kvp.Value as Series;
                    if (ts.type == ESeriesType.ArraySuper) new Error("Internal error #78yuasfasdf32");

                    TraceHelper th1 = new TraceHelper();
                    th1.type = ETraceHelper.GetAllMetasAndTraces;
                    if (direct == 1) th1.depthLimit = 1;
                    ts.DeepTrace(th1);                    

                    foreach (Trace2 trace in th1.traces.Keys)
                    {
                        TraceGetDependentsHelper(null, trace, bankname, found, kvp.Key);
                    }
                }
            }
            else
            {
                string nameWithFreq = null;
                if (ivName.Type() == EVariableType.String)
                {
                    nameWithFreq = G.Chop_AddFreq(G.Chop_GetName(O.ConvertToString(ivName)), Program.options.freq);                    
                }
                else if (ivName.Type() == EVariableType.Series)
                {
                    nameWithFreq = (ivName as Series).GetName();
                }

                GekkoDictionary<string, IVariable> flat = Program.databanks.GetFirst().StorageFlattenedArrayTimeseries();
                foreach (KeyValuePair<string, IVariable> kvp in flat)
                {
                    if (kvp.Value.Type() != EVariableType.Series) continue;
                    Series ts = kvp.Value as Series;
                    if (ts.type == ESeriesType.ArraySuper) new Error("Internal error #78yuasfasdf32");

                    TraceHelper th1 = new TraceHelper();
                    th1.type = ETraceHelper.GetAllMetasAndTraces;
                    if (direct == 1) th1.depthLimit = 1;
                    ts.DeepTrace(th1);

                    foreach (Trace2 trace in th1.traces.Keys)
                    {
                        TraceGetDependentsHelper(nameWithFreq, trace, bankname, found, kvp.Key);
                    }
                }
            }

            return found;
        }

        private static void TraceGetDependentsHelper(string adamName, Trace2 trace, string bankname, GekkoDictionary<string, bool> found, string dependentName)
        {
            List<string> precedentsNames = trace.traceContents.precedentsNames;
            if (precedentsNames != null)
            {
                foreach (string pname in precedentsNames)
                {
                    string aname = TraceGetPrecedentsHelper2(bankname, pname);
                    if (aname != null)
                    {
                        if (adamName == null || G.Equal(aname, adamName))
                        {
                            if (!found.ContainsKey(dependentName))
                                found.Add(dependentName, false);
                        }
                    }
                }
            }
        }


        /// <summary>
        /// Error message.
        /// </summary>
        /// <param name="lineNumber"></param>
        /// <param name="problemLine"></param>
        /// <param name="text"></param>
        /// <param name="fileName"></param>
        public static void WriteErrorMessage(int lineNumber, string problemLine, string text, string fileName)
        {
            if (Globals.threadIsInProcessOfAborting) return;
            if (P.IsFunctionOrProcedure(fileName)) return; //the line will not make sense for that case
            G.Writeln(text, Color.Red, true);  //will also be red for a STOP statement, but without counting as an error
            G.Writeln("    " + "[" + G.IntFormat(lineNumber, 4) + "]:" + "   " + G.ReplaceGlueSymbols(problemLine), Color.Blue, true);
        }

