        /// <summary>
        /// Get name, label, source, unit, etc. for a timeseries (will also get lines from external varlist.dat file if present: these lines are shown right after name)
        /// </summary>
        /// <param name="varnameWithoutFreq"></param>
        /// <param name="printName"></param>
        /// <param name="printData"></param>
        /// <param name="tStart"></param>
        /// <param name="tEnd"></param>
        /// <returns></returns>
        public static List<string> GetVariableExplanation(DName varname, bool printName, bool printData, GekkoTime tStart, GekkoTime tEnd, HtmlBrowserSettings htmlBrowserSettings, bool mayGiveExceptionError)
        {
            //For Gekko 4.0, clean up the two first parameters (should be just 1).
            //For Gekko 4.0, think about using G.ReplaceWhitespaceWith1Blank() on each line in return list rv.
            //Or make sure the label, source etc. objects are cleaned with ReplaceWhitespaceWith1Blank().

            bool danish = false;
            if (htmlBrowserSettings != null && htmlBrowserSettings.isDanish) danish = true;

            List<string> rv = new List<string>();
            IVariable iv = null;
            if (mayGiveExceptionError) iv = O.GetIVariableFromString(varname.ToString(), O.ECreatePossibilities.NoneReturnNullButErrorForParentArraySeries, false);
            else
            {
                iv = O.GetIVariableFromString(varname.ToString(), O.ECreatePossibilities.NoneReturnNullAlways, false);
                if (iv == null) return rv;
            }
            Series ts = null;
            if (iv != null) ts = iv as Series;
            if (printName)
            {                
                string sDomains = null;
                if (ts?.mmi != null)
                {
                    //then it is a sub-series
                    Series parent = ts.mmi.parent;
                    double dimCount2 = 1d;
                    string dimCount = null;
                    List<List<string>> elements = new List<List<string>>();
                    List<string> domains = new List<string>();
                    List<MultidimElement> keys = parent.GetSortedDimensionKeys();
                    DispHelperArraySeries2(parent, keys, ref dimCount2, ref dimCount, elements, domains);
                    if (domains.Count > 0)
                    {
                        sDomains = ", domains: [" + Stringlist.GetListWithCommas(domains) + "]";
                    }
                }
                GekkoTimeSpans fixList = null;
                try
                {                    
                    if (Program.model.modelCommon.GetModelSourceType() == EModelType.GAMSScalar)
                    {                        
                        fixList = GekkoTimeSpans.GetTimeSpansFromGekkoTimeArray(Program.model.modelGamsScalar.GetFixedPeriods(varname));
                    }
                }
                catch { } //No need to crash on this, the try-catch can be removed in Gekko 4.0
                string fixes = null;
                if (fixList != null && fixList.data.Count != 0) fixes = ", modelfix: " + fixList.ToString();
                rv.Add("Series: " + varname.ToString() + sDomains + fixes);
            }

            List<string> explanationsFromExternalFile = Program.GetVariableExplanationFromExternalFile(varname.ToStringWithoutFreq());
            foreach (string line in explanationsFromExternalFile)
            {
                if (line != "")
                {
                    rv.Add(line);
                }
            }

            try
            {
                if (ts != null)
                {
                    if (ts.type == ESeriesType.Normal || ts.type == ESeriesType.Timeless || ts.type == ESeriesType.ArraySuper)
                    {
                        string label_string = "";  //DGR asked to omit "Label: ", and it is typically pretty obvious anyway.
                        string source_string = Globals.Source + ": "; if (danish) source_string = "Kilde: ";
                        string units_string = Globals.Units + ": "; if (danish) units_string = "Enhed: ";  //DGR asked to change from Enheder --> Enhed.

                        string label2 = ts.MetaGetLabel();
                        if (label2 != null) rv.Add(label_string + label2);

                        string source2 = ts.MetaGetSource();
                        if (source2 != null && !(htmlBrowserSettings != null && htmlBrowserSettings.show_source == false)) rv.Add(source_string + source2);

                        string units2 = ts.MetaGetUnits();
                        if (units2 != null) rv.Add(units_string + units2);
                    }

                    if (printData)
                    {

                        rv.Add("-----------------------------------------------");
                        rv.Add("Period        value        %");

                        int counter = 0;

                        //must be able to handle TIME where freq does not match the series freq
                        foreach (GekkoTime gt in new GekkoTimeIterator(Program.ConvertFreqs(tStart, tEnd, ts.freq)))
                        {
                            counter++;
                            string sss = gt.ToString() + " ";  //see how it is done with a table here: #kj3ha3438u

                            double n1 = ts.GetDataSimple(gt);
                            double n0 = ts.GetDataSimple(gt.Add(-1));

                            double level1 = n1;
                            double pch1 = ((n1 / n0 - 1) * 100d);

                            if (n1 == n0) pch1 = 0d;

                            string levelFormatted;
                            string pchFormatted;
                            Program.ConvertToPrintFormat(level1, pch1, out levelFormatted, out pchFormatted);

                            sss += levelFormatted + " " + pchFormatted + " ";
                            rv.Add(sss);
                        }
                    }
                }
            }
            catch
            {
                //no need to fail on this
            }
            return rv;
        }

