        /// <summary>
        /// Used for DELETE&lt;nonmodel&gt;
        /// </summary>
        public static void Trimvars()
        {
            if (G.GetModelSourceType() != EModelType.Gekko)
            {
                new Error("No Gekko model is defined for trimming, cf. MODEL statement.");
                //throw new GekkoException();
            }

            List<Databank> banks = new List<Databank> { Program.databanks.GetFirst(), Program.databanks.GetRef() };

            G.Writeln();
            foreach (Databank bank in banks)
            {
                List<string> onlyDatabankNotModel = new List<string>();
                foreach (KeyValuePair<string, IVariable> s in bank.storage)
                {
                    if (s.Value.Type() != EVariableType.Series) continue;
                    if (G.GetFreqFromName(s.Key) != Program.options.freq) continue;  //filter out other freqs
                    string s2 = G.Chop_RemoveFreq(s.Key);
                    if (!Program.model.modelGekko.varsAType.ContainsKey(new DNameSimplest(s2)))
                    {
                        onlyDatabankNotModel.Add(s2);
                    }
                }

                int c = 0;
                foreach (string s in onlyDatabankNotModel)
                {
                    string ss = s + Globals.freqIndicator + G.ConvertFreq(Program.options.freq);
                    if (bank.ContainsIVariable(ss))
                    {
                        bank.RemoveIVariable(ss);
                        c++;
                    }
                }
                G.Writeln2("Removed " + c + " variable(s) in '" + bank.name + "' databank");
            }
        }

        /// <summary>
        /// FINDMISSINGDATA statement.
        /// </summary>
        /// <param name="o"></param>
        public static void FindMissingData(O.Findmissingdata o)
        {
            GekkoTime tStart = o.t1;
            GekkoTime tEnd = o.t2;

            List vars2 = O.Restrict2(o.names, false, false, false, false);   //only allows plain vars (idents)
            List<ToFrom> vars = null;
            if (vars2 != null) vars = SearchFromTo(vars2, null, null, null, EWildcardSearchType.Search, null);

            bool replace = true;
            if (double.IsNaN(o.opt_replace)) replace = false;

            bool hasFilter = false;
            bool hasModel = false;

            Databank work = Program.databanks.GetFirst();

            Dictionary<string, string> exod = null;
            Dictionary<string, string> exoj = null;
            Dictionary<string, string> exoz = null;
            Dictionary<string, string> exodjz = null;
            Dictionary<string, string> exo = null;
            Dictionary<string, string> exotrue = null;
            Dictionary<string, string> endo = null;
            Dictionary<string, string> all = null;

            if (!replace)
            {
                exod = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                exoj = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                exoz = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                exodjz = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                exo = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                exotrue = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                endo = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                all = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            }

            if ((G.GetModelSourceType() != EModelType.Gekko) || replace)
            {
            }
            else
            {
                hasModel = true;
                try
                {
                    foreach (string s in Stringlist.GetListOfStringsFromListOfIvariables(((List)O.GetIVariableFromString("global:" + Globals.symbolCollection + "exod", O.ECreatePossibilities.NoneReturnNullButErrorForParentArraySeries)).list.ToArray()))
                        exod.Add(s, "");
                    foreach (string s in Stringlist.GetListOfStringsFromListOfIvariables(((List)O.GetIVariableFromString("global:" + Globals.symbolCollection + "exoj", O.ECreatePossibilities.NoneReturnNullButErrorForParentArraySeries)).list.ToArray()))
                        exoj.Add(s, "");
                    foreach (string s in Stringlist.GetListOfStringsFromListOfIvariables(((List)O.GetIVariableFromString("global:" + Globals.symbolCollection + "exoz", O.ECreatePossibilities.NoneReturnNullButErrorForParentArraySeries)).list.ToArray()))
                        exoz.Add(s, "");
                    foreach (string s in Stringlist.GetListOfStringsFromListOfIvariables(((List)O.GetIVariableFromString("global:" + Globals.symbolCollection + "exodjz", O.ECreatePossibilities.NoneReturnNullButErrorForParentArraySeries)).list.ToArray()))
                        exodjz.Add(s, "");
                    foreach (string s in Stringlist.GetListOfStringsFromListOfIvariables(((List)O.GetIVariableFromString("global:" + Globals.symbolCollection + "exo", O.ECreatePossibilities.NoneReturnNullButErrorForParentArraySeries)).list.ToArray()))
                        exo.Add(s, "");
                    foreach (string s in Stringlist.GetListOfStringsFromListOfIvariables(((List)O.GetIVariableFromString("global:" + Globals.symbolCollection + "exotrue", O.ECreatePossibilities.NoneReturnNullButErrorForParentArraySeries)).list.ToArray()))
                        exotrue.Add(s, "");
                    foreach (string s in Stringlist.GetListOfStringsFromListOfIvariables(((List)O.GetIVariableFromString("global:" + Globals.symbolCollection + "endo", O.ECreatePossibilities.NoneReturnNullButErrorForParentArraySeries)).list.ToArray()))
                        endo.Add(s, "");
                    foreach (string s in Stringlist.GetListOfStringsFromListOfIvariables(((List)O.GetIVariableFromString("global:" + Globals.symbolCollection + "all", O.ECreatePossibilities.NoneReturnNullButErrorForParentArraySeries)).list.ToArray()))
                        all.Add(s, "");
                }
                catch { };  //if error, we just ignore it, and the list will be empty.
            }

            Dictionary<string, string> filter = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            //exod
            //exoj
            //exoz
            //exodjz
            //exo
            //exotrue
            //endo
            //all
            //work

            List<string> missing_exod = null;
            List<string> missing_exoj = null;
            List<string> missing_exoz = null;
            List<string> missing_exodjz = null;
            List<string> missing_exo = null;
            List<string> missing_exotrue = null;
            List<string> missing_endo = null;
            List<string> missing_all = null;
            List<string> missing_ = null;

            if (!replace)
            {
                missing_exod = new List<string>();
                missing_exoj = new List<string>();
                missing_exoz = new List<string>();
                missing_exodjz = new List<string>();
                missing_exo = new List<string>();
                missing_exotrue = new List<string>();
                missing_endo = new List<string>();
                missing_all = new List<string>();  //every variable in model
                missing_ = new List<string>();   //every model i work databank (this typically includes the "all" set, because the READ statement auto-creates model variables if they are not in the databank)
            }

            if (vars != null)  //if filter is set
            {
                hasFilter = true;
                foreach (ToFrom tf in vars)
                {
                    filter.Add(tf.s1, "");  //we are just using the keys, not values, therefore ""
                }
            }

            foreach (KeyValuePair<string, IVariable> kvp in work.storage)
            //all variables in work databank
            //foreach (string ss in work.storage.Keys)
            {
                if (kvp.Value.Type() != EVariableType.Series) continue;
                string ss = kvp.Key;
                if (G.GetFreqFromName(ss) != Program.options.freq) continue;  //we filter out other freqs
                string s = G.Chop_RemoveFreq(ss);

                if (hasFilter)
                {
                    if (!filter.ContainsKey(s)) continue;  //ignore this
                }
                Series ts = kvp.Value as Series;
                //Series ts = work.GetVariable(s);  //can this not be moved before loop??  //#getvar

                List<Series> l = new List<Series>();
                List<string> n = new List<string>();

                if (ts.type == ESeriesType.ArraySuper)
                {
                    foreach (KeyValuePair<MultidimElement, IVariable> kvpsub in ts.dimensionsStorage.storage)
                    {
                        Series sub = kvpsub.Value as Series;
                        l.Add(sub);
                        n.Add(sub.GetNameWithoutCurrentFreq(true));
                    }
                }
                else
                {
                    l.Add(ts);
                    n.Add(s);
                }

                for (int i = 0; i < l.Count; i++)
                {

                    foreach (GekkoTime t in new GekkoTimeIterator(tStart, tEnd))
                    {
                        double value = l[i].GetDataSimple(t);
                        if (G.IsNumericalError(value))
                        {
                            if (replace)
                            {
                                l[i].SetData(t, o.opt_replace);
                            }
                            else
                            {
                                missing_.Add(n[i]);  //always put it in this list
                                if (exod.ContainsKey(n[i])) missing_exod.Add(s);
                                if (exoj.ContainsKey(n[i])) missing_exoj.Add(s);
                                if (exoz.ContainsKey(n[i])) missing_exoz.Add(s);
                                if (exodjz.ContainsKey(n[i])) missing_exodjz.Add(s);
                                if (exo.ContainsKey(n[i])) missing_exo.Add(s);
                                if (exotrue.ContainsKey(n[i])) missing_exotrue.Add(s);
                                if (endo.ContainsKey(n[i])) missing_endo.Add(s);
                                if (all.ContainsKey(n[i])) missing_all.Add(s);
                                break;  //one is enough
                            }
                        }
                    }
                }
            }

            if (!replace)
            {

                Dictionary<string, List<string>> names = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
                names.Add("missingdata_", missing_);  //this one is a bit special
                names.Add("missingdata_exod", missing_exod);
                names.Add("missingdata_exoj", missing_exoj);
                names.Add("missingdata_exoz", missing_exoz);
                names.Add("missingdata_exodjz", missing_exodjz);
                names.Add("missingdata_exo", missing_exo);
                names.Add("missingdata_exotrue", missing_exotrue);
                names.Add("missingdata_endo", missing_endo);
                names.Add("missingdata_all", missing_all);

                List<string> names2 = new List<string>();
                names2.Add("missingdata_");
                if (hasModel)
                {
                    names2.Add("missingdata_all");
                    names2.Add("missingdata_endo");
                    names2.Add("missingdata_exotrue");
                    names2.Add("missingdata_exo");
                    names2.Add("missingdata_exodjz");
                    names2.Add("missingdata_exod");
                    names2.Add("missingdata_exoj");
                    names2.Add("missingdata_exoz");
                }

                G.Writeln();
                G.Writeln("------------------------ Report: Find missing data -------------------------------");
                G.Writeln();
                if (G.GetModelSourceType() != EModelType.Gekko)
                {
                    G.Writeln();
                    G.Writeln("No Gekko model seems to be loaded -- result cannot be split into exogenous, endogenous etc. variables");
                    G.Writeln();
                }

                foreach (string n2 in names2)
                {
                    List<string> list = names[n2];
                    string listname = n2;
                    if (listname == "missingdata_") listname = "missingdata";

                    if (true)
                    {
                        list.Sort();
                        Program.databanks.GetFirst().AddIVariableWithOverwrite(Globals.symbolCollection + listname, new List(list));

                        if (list.Count > 0)
                        {
                            string v = "variables";
                            if (list.Count == 1) v = "variable";
                            G.Writeln("List #" + listname + " has " + list.Count + " " + v + ":");
                            G.PrintListWithCommas(list, false);
                            G.Writeln();
                        }
                        else
                        {
                            G.Writeln("List #" + listname + " is empty");
                            G.Writeln();
                        }
                    }
                }
                G.Writeln("------------------------ Report end ----------------------------------------------");
                G.Writeln();
                G.Writeln();
            }
        }

        /// <summary>
        /// Helper for options that may be both yes, no or null.
        /// </summary>
        /// <param name="opt"></param>
        /// <returns></returns>
        //See #98745239543
        public static YesNoNull GetYesNoNullLocalOption(string opt)
        {
            YesNoNull rv = YesNoNull.Null;
            if (opt == null) rv = YesNoNull.Null;
            else if (G.Equal(opt, "yes")) rv = YesNoNull.Yes;
            else if (G.Equal(opt, "no")) rv = YesNoNull.No;
            else
            {
                new Error("Expected 'yes' or 'no', not '" + opt + "'");
                //throw new GekkoException();
            }
            return rv;
        }

        /// <summary>
        /// Used for compareFolders() function.
        /// </summary>
        /// <param name="f1"></param>
        /// <param name="f2"></param>
        /// <param name="f3"></param>
        /// <param name="f4"></param>
        public static void CompareFolders(string f1, string f2, string f3, string f4)
        {
            //TODO: warn or skip if some folder is a .git folder.

            string omit = "\\.git";  //takes care of .gitignore etc.

            DateTime t0 = DateTime.Now;

            f1 = G.CleanupFolderName(f1, true);
            f2 = G.CleanupFolderName(f2, true);

            var xd1 = Directory.EnumerateFiles(f1, "*", SearchOption.AllDirectories).Where(p => !G.Contains(p, omit)).Select(Path.GetFullPath).Select(x => G.Replace(x, f1, "", StringComparison.OrdinalIgnoreCase, 0)).OrderBy(x => x);
            var xd2 = Directory.EnumerateFiles(f2, "*", SearchOption.AllDirectories).Where(p => !G.Contains(p, omit)).Select(Path.GetFullPath).Select(x => G.Replace(x, f2, "", StringComparison.OrdinalIgnoreCase, 0)).OrderBy(x => x);

            bool option_text = false;
            bool option_strict = false;
            bool option_date = false;
            if (!G.NullOrBlanks(f4))
            {
                if (G.ContainsWord(f4, "text")) option_text = true;
                if (G.ContainsWord(f4, "strict")) option_strict = true;
                if (G.ContainsWord(f4, "date")) option_date = true;
            }

            if (option_strict && option_date) new Error("You cannot use 'strict' and 'date' at the same time");

            List<string> black = new List<string>();
            List<string> white = new List<string>();
            if (!G.NullOrBlanks(f3))
            {
                string[] ss = f3.Split(',');
                foreach (string s2 in ss)
                {
                    string s = s2.Trim();
                    if (!G.NullOrBlanks(s))
                    {
                        if (s.StartsWith("!"))
                        {
                            black.Add(s.Substring(1));
                        }
                        else
                        {
                            white.Add(s);
                        }
                    }
                }
            }

            List<Wildcard> wblack = new List<Wildcard>();
            foreach (string s in black) wblack.Add(new Wildcard(s, System.Text.RegularExpressions.RegexOptions.IgnoreCase));
            List<Wildcard> wwhite = new List<Wildcard>();
            foreach (string s in white) wwhite.Add(new Wildcard(s, System.Text.RegularExpressions.RegexOptions.IgnoreCase));
            List<string> d1 = MatchInBlackWhiteWildcards(xd1, wblack, wwhite);
            List<string> d2 = MatchInBlackWhiteWildcards(xd2, wblack, wwhite);

            var e12 = d1.Except(d2, StringComparer.OrdinalIgnoreCase).Distinct().ToArray();
            var e21 = d2.Except(d1, StringComparer.OrdinalIgnoreCase).Distinct().ToArray();
            var intersect_temp = d1.Intersect(d2, StringComparer.OrdinalIgnoreCase).Distinct().ToArray();

            List<string> differentBinary = new List<string>();
            List<string> differentText = new List<string>();
            List<string> differentAll = new List<string>();

            //Some double work, but should still be fast
            List<string> intersect = new List<string>();
            foreach (string s in intersect_temp)
            {
                if (option_text)
                {
                    string p1 = f1 + "\\" + s;
                    string p2 = f2 + "\\" + s;
                    bool isText = !G.IsBinary(p1) && !G.IsBinary(p2);
                    if (!isText) continue;  //skip it
                }
                intersect.Add(s);
            }

            string extra = null;
            string extra2 = null;
            if (intersect_temp.Length - intersect.Count > 0)
            {
                extra = " (" + (intersect_temp.Length - intersect.Count) + " skipped binary files)";
                extra2 = " text";
            }

            new Writeln("Comparing " + intersect.Count + extra2 + " files" + extra);

            List<int> fractions; List<double> fractions2;
            G.GetFractions(intersect.Count, out fractions, out fractions2);

            int lineCounter = 0;
            foreach (string s in intersect)
            {
                lineCounter++;
                G.CheckFractions(lineCounter, intersect.Count, 1000, fractions, fractions2);

                string p1 = f1 + "\\" + s;
                string p2 = f2 + "\\" + s;

                bool identical = G.CompareFiles(p1, p2, option_strict, option_date);  //could speed up more by parallelizing the whole intersect list.

                if (!identical)
                {
                    bool isText = !G.IsBinary(p1) && !G.IsBinary(p2);
                    if (isText)
                    {
                        //Two text files may have same contents when ignoring blanks etc.
                        List<string> ss1 = Stringlist.ExtractLinesFromText(File.ReadAllText(p1));
                        List<string> ss2 = Stringlist.ExtractLinesFromText(File.ReadAllText(p2));

                        //TODO: Maybe allow blank lines to differ??
                        if (ss1.Count == ss2.Count)
                        {
                            bool same = true;
                            for (int i = 0; i < ss1.Count; i++)
                            {
                                if (ss1[i].Trim() != ss2[i].Trim())
                                {
                                    //Beware that this removes tabs in Python files (in practice hard to see that this should possibly be a problem regarding equality)
                                    //On the positive side, it removes quite a lot of noise like file endings etc.
                                    //Differing blank lines will render the files different
                                    same = false;
                                    break;
                                }
                            }
                            if (same) identical = true;  //the two text files are the same line by line, if stuff like tabs + blanks (whitespace) are trimmed off at start/end of line
                        }
                    }
                    if (isText) differentText.Add(s);
                    else differentBinary.Add(s);
                    differentAll.Add(s);
                }
            }

            //
            // ------- comparefolders2.zip
            //            

            Zipper zipper2 = new Zipper("comparefolders2.zip");
            GekkoDictionary<string, bool> missingFolders1 = new GekkoDictionary<string, bool>(StringComparer.OrdinalIgnoreCase);
            GekkoDictionary<string, bool> missingFolders2 = new GekkoDictionary<string, bool>(StringComparer.OrdinalIgnoreCase);
            
            if (true)
            {                
                StringBuilder sb = new StringBuilder();
                sb.AppendLine("// ========== From folder2 to folder1: copy files that are missing in folder1 ==========");
                foreach (string s in e21)
                {
                    if (!Directory.Exists(Path.GetDirectoryName(f1 + s)))
                    {
                        if (!missingFolders1.ContainsKey(Path.GetDirectoryName(f1 + s))) missingFolders1.Add(Path.GetDirectoryName(f1 + s), false);
                    }
                    sb.AppendLine("sys 'copy \"" + f2 + s + "\" \"" + f1 + s + "\"';");
                }
                sb.AppendLine("");
                sb.AppendLine("// ========== From folder2 to folder1: overwrite common files that are different (binary) ==========");
                foreach (string s in differentBinary)
                {
                    sb.AppendLine("sys 'copy /y \"" + f2 + s + "\" \"" + f1 + s + "\"';");
                }
                sb.AppendLine("");
                sb.AppendLine("// ========== From folder2 to folder1: overwrite common files that are different (text) ==========");
                foreach (string s in differentText)
                {
                    sb.AppendLine("sys 'copy /y \"" + f2 + s + "\" \"" + f1 + s + "\"';");
                }

                if (missingFolders1.Count > 0)
                {
                    sb.AppendLine();
                    sb.AppendLine("/*");
                    sb.AppendLine("-------------------------------------------------------------------");
                    sb.AppendLine("In folder1, the following subfolders from folder2 do not exist:");
                    foreach (string s in missingFolders1.Keys)
                    {
                        sb.AppendLine(G.Replace(s, f1, "", StringComparison.OrdinalIgnoreCase, 0));
                    }
                    sb.AppendLine("*/");
                }

                File.WriteAllText(zipper2.tempFolder + "\\" + "updatefolder1.gcm", sb.ToString());
            }

            if (true)
            {                 
                StringBuilder sb = new StringBuilder();
                sb.AppendLine("// ========== From folder1 to folder2: copy files that are missing in folder2 ==========");
                foreach (string s in e12)
                {
                    if (!Directory.Exists(Path.GetDirectoryName(f2 + s)))
                    {
                        if (!missingFolders2.ContainsKey(Path.GetDirectoryName(f2 + s))) missingFolders2.Add(Path.GetDirectoryName(f2 + s), false);
                    }
                    sb.AppendLine("sys 'copy \"" + f1 + s + "\" \"" + f2 + s + "\"';");
                }
                sb.AppendLine("");
                sb.AppendLine("// ========== From folder1 to folder2: overwrite common files that are different (binary) ==========");
                foreach (string s in differentBinary)
                {
                    sb.AppendLine("sys 'copy /y \"" + f1 + s + "\" \"" + f2 + s + "\"';");
                }
                sb.AppendLine("");
                sb.AppendLine("// ========== From folder1 to folder2: overwrite common files that are different (text) ==========");
                foreach (string s in differentText)
                {
                    sb.AppendLine("sys 'copy /y \"" + f1 + s + "\" \"" + f2 + s + "\"';");
                }

                if (missingFolders2.Count > 0)
                {
                    sb.AppendLine();
                    sb.AppendLine("/*");
                    sb.AppendLine("-------------------------------------------------------------------");
                    sb.AppendLine("In folder2, the following subfolders from folder1 do not exist:");
                    foreach (string s in missingFolders2.Keys)
                    {
                        sb.AppendLine(G.Replace(s, f2, "", StringComparison.OrdinalIgnoreCase, 0));
                    }
                    sb.AppendLine("*/");
                }

                File.WriteAllText(zipper2.tempFolder + "\\" + "updatefolder2.gcm", sb.ToString());
            }
            zipper2.ZipAndCleanup();

            StringBuilder sb2 = new StringBuilder();

            using (var txt = new Writeln())
            {
                txt.MainAdd("Finished compareFolders() in " + G.SecondsFormat((DateTime.Now - t0).TotalMilliseconds));
                sb2.AppendLine("Finished compareFolders() in " + G.SecondsFormat((DateTime.Now - t0).TotalMilliseconds));
                txt.MainNewLineTight();

                txt.MainAdd("Folder1 = " + f1);
                sb2.AppendLine("Folder1 = " + f1);
                txt.MainNewLineTight();

                txt.MainAdd("Folder2 = " + f2);
                sb2.AppendLine("Folder2 = " + f2);
                txt.MainNewLineTight();

                if (!G.NullOrBlanks(f3))
                {
                    txt.MainAdd("Filters = " + f3);
                    sb2.AppendLine("Filters = " + f3);
                    txt.MainNewLineTight();
                }

                if (option_text)
                {
                    txt.MainAdd("Option 'text': only text files are compared");
                    sb2.AppendLine("Option 'text': only text files are compared");
                    txt.MainNewLineTight();
                }

                if (option_strict)
                {
                    txt.MainAdd("Option 'strict': files dates not used in file comparison");
                    sb2.AppendLine("Option 'strict': files dates not used in file comparison");
                    txt.MainNewLineTight();
                }

                if (option_date)
                {
                    txt.MainAdd("Option 'date': files dates rather than contents are used to compare files");
                    sb2.AppendLine("Option 'date': files dates rather than contents are used to compare files");
                    txt.MainNewLineTight();
                }

                txt.MainAdd(intersect.Count() + " common files, of which " + differentAll.Count + " are different");
                sb2.AppendLine(intersect.Count() + " common files, of which " + differentAll.Count + " are different");
                txt.MainNewLineTight();

                txt.MainAdd(e12.Count() + " files from folder1 do not exist in folder2");
                sb2.AppendLine(e12.Count() + " files from folder1 do not exist in folder2");
                txt.MainNewLineTight();

                txt.MainAdd(e21.Count() + " files from folder2 do not exist in folder1");
                sb2.AppendLine(e21.Count() + " files from folder2 do not exist in folder1");
                txt.MainNewLineTight();

                if (missingFolders1.Count > 0)
                {
                    txt.MainAdd(missingFolders1.Count + " subfolders are missing in folder1");
                    sb2.AppendLine(missingFolders1.Count + " subfolders are missing in folder1");
                    txt.MainNewLineTight();
                }

                if (missingFolders2.Count > 0)
                {
                    txt.MainAdd(missingFolders2.Count + " subfolders are missing in folder2");
                    sb2.AppendLine(missingFolders2.Count + " subfolders are missing in folder2");
                    txt.MainNewLineTight();
                }
            }

            //
            // ------- comparefolders1.zip
            //

            if (true)
            {
                Zipper zipper1 = new Zipper("comparefolders1.zip");
                foreach (string s in differentText)
                {
                    string a1 = f1 + s;
                    string b1 = zipper1.tempFolder + "\\" + Path.GetDirectoryName(s).Replace("\\", "--") + "--" + Path.GetFileNameWithoutExtension(s).Replace(".", ",") + "," + Path.GetExtension(s).Replace(".", "") + " (1)";
                    File.Copy(a1, b1);
                    string a2 = f2 + s;
                    string b2 = zipper1.tempFolder + "\\" + Path.GetDirectoryName(s).Replace("\\", "--") + "--" + Path.GetFileNameWithoutExtension(s).Replace(".", ",") + "," + Path.GetExtension(s).Replace(".", "") + " (2)";
                    File.Copy(a2, b2);
                }
                zipper1.ZipAndCleanup();
            }

            //
            // ------- comparefolders.txt
            //

            sb2.AppendLine();
            sb2.AppendLine("========== " + intersect.Count() + " common files" + " ==========");
            foreach (string s in intersect)
            {
                sb2.AppendLine(s);
            }

            sb2.AppendLine();
            sb2.AppendLine("========== " + e12.Count() + " files in folder1, but not in folder2:" + " ==========");
            foreach (string s in e12)
            {
                sb2.AppendLine(s);
            }

            sb2.AppendLine();
            sb2.AppendLine("========== " + e21.Count() + " files in folder2, but not in folder1:" + " ==========");
            foreach (string s in e21)
            {
                sb2.AppendLine(s);
            }

            sb2.AppendLine();
            sb2.AppendLine("========== " + differentBinary.Count + " different common files (binary):" + " ==========");
            foreach (string s in differentBinary)
            {
                sb2.AppendLine(s);
            }

            sb2.AppendLine();
            sb2.AppendLine("========== " + differentText.Count + " different common files (text):" + " ==========");
            foreach (string s in differentText)
            {
                sb2.AppendLine(s);
            }

            File.WriteAllText("comparefolders.txt", sb2.ToString());

            using (var txt = new Writeln())
            {
                txt.MainAdd("File comparefolders.txt contains lists of file differences");
                txt.MainNewLineTight();
                txt.MainAdd("File comparefolders1.zip contains differing text files for easy comparison");
                txt.MainNewLineTight();
                txt.MainAdd("File comparefolders2.zip contains Gekko code to update folder1 or folder2");
            }
        }



        /// <summary>
        /// Input is a list of fileNameWithPaths. Will only look at filenames.
        /// </summary>
        /// <param name="names"></param>
        /// <param name="wblack"></param>
        /// <param name="wwhite"></param>
        /// <returns></returns>
        private static List<string> MatchInBlackWhiteWildcards(IOrderedEnumerable<string> names, List<Wildcard> wblack, List<Wildcard> wwhite)
        {
            List<string> result = new List<string>();
            foreach (string s2 in names)
            {
                bool ok = false;
                string s = Path.GetFileName(s2);

                if (wwhite.Count == 0)
                {
                    ok = true;
                }
                else
                {
                    foreach (Wildcard wp in wwhite)
                    {
                        if (wp.IsMatch(s))
                        {
                            ok = true;
                            break;
                        }
                    }
                }

                if (ok)
                {
                    foreach (Wildcard wn in wblack)
                    {
                        if (wn.IsMatch(s))
                        {
                            ok = false;
                            break;
                        }
                    }
                }
                if (ok) result.Add(s2);
            }
            return result;
        }

        /// <summary>
        /// ITERSHOW statement.
        /// </summary>
        /// <param name="vars"></param>
        /// <param name="t1"></param>
        /// <param name="t2"></param>
        public static void Itershow(List<string> vars, GekkoTime t1, GekkoTime t2)
        {
            if (G.GetModelSourceType() != EModelType.Gekko)
            {
                new Error("No Gekko model seems to be defined, see MODEL statement.");
                //throw new GekkoException();
            }

            bool hasContent = false;

            Table tab = new Table();
            int row = 1;

            List<string> problems = new List<string>();

            foreach (string var in vars)
            {
                bool hasDifference = false;
                foreach (GekkoTime t in new GekkoTimeIterator(t1, t2))
                {
                    int rowYearStart = row;
                    List<IterMemory> iterMemories = null;
                    if (Program.model.modelGekko.bMemory.ContainsKey(t))
                    {
                        iterMemories = Program.model.modelGekko.bMemory[t];
                    }
                    else
                    {
                        G.Writeln("There were no recorded iterations in memory regarding period " + t.ToString());
                        continue;
                    }

                    hasContent = true;

                    tab.Set(row, 1, t.ToString());
                    tab.Set(row, 2, G.GetUpperLowerCase(var));
                    row++;
                    tab.Set(row, 1, "Iter");
                    tab.Set(row, 2, "Before");
                    tab.Set(row, 3, "After");
                    tab.Set(row, 4, "Hist. var");
                    tab.Set(row, 5, "Difference");
                    tab.Set(row, 6, "Relative1");
                    tab.Set(row, 7, "Relative2");
                    tab.SetAlign(row, 1, row, 7, Align.Right);
                    tab.SetBorder(row, 1, row, 7, BorderType.Top);
                    tab.SetBorder(row, 1, row, 7, BorderType.Bottom);

                    for (int it = 0; it < iterMemories.Count; it++)
                    {
                        IterMemory iterMemory = iterMemories[it];
                        double[] bBefore = iterMemory.bBefore;
                        double[] bAfter = iterMemory.bAfter;

                        EquationHelper found = Program.FindEquationByMeansOfVariableName(new DNameSimplest(var));
                        if (found == null)
                        {
                            //G.Writeln();
                            new Error("ITERSHOW: Variable " + var + " is not endogenous");
                            //throw new GekkoException();
                        }
                        int i = found.bNumberLhs;
                        //G.Writeln("per " + t.ToString() + " it " + it + " bef " + bBefore[i] + " aft " + bAfter[i]);
                        row++;
                        double bOld = bBefore[i];
                        double b = bAfter[i];
                        double bVariance = Program.model.modelGekko.bVariance[i];

                        tab.Set(new Coord(row, 1), "", it + 1, CellType.Number, "f6.0");
                        tab.Set(new Coord(row, 2), "", bOld, CellType.Number, "f13.4");
                        tab.Set(new Coord(row, 3), "", b, CellType.Number, "f13.4");
                        tab.Set(new Coord(row, 4), "", bVariance, CellType.Number, "f13.4");

                        double abs = (b - bOld);
                        double rel = (abs / bOld);
                        double relHist = (abs / bVariance);

                        if (abs != 0d) hasDifference = true;

                        tab.Set(new Coord(row, 5), "", abs, CellType.Number, "f15.6");
                        tab.Set(new Coord(row, 6), "", relHist, CellType.Number, "f12.6");
                        tab.Set(new Coord(row, 7), "", rel, CellType.Number, "f12.6");
                    }
                    tab.SetBorder(row, 1, row, 7, BorderType.Bottom);
                    tab.SetBorder(rowYearStart + 1, 1, row, 1, BorderType.Left);
                    tab.SetBorder(rowYearStart + 1, 7, row, 7, BorderType.Right);
                    row++;
                    row++;

                }//time loop
                if (!hasDifference) problems.Add(var);
            }
            if (hasContent)
            {
                O.PrintTable(tab, false, null);
                if (problems.Count > 0)
                {
                    G.Writeln();
                    foreach (string s in problems)
                    {
                        new Note("Variable '" + s + "' might be part of the prologue or epilogue, and if so it does not change during Gauss iterations. Regarding ordering, see the [model]__info.zip file, inside [model].ordering.");
                    }
                }
                new Note("Damped variables have stricter convergence crits than non-damped.");
            }
            else
            {
                G.Writeln();
                G.Writeln("It seems there was no results stored regarding iterations: did you remember to set 'OPTION solve gauss dump = yes' before simulation?");
            }
        }

        /// <summary>
        /// Print some links for SIM. TODO: use GekkoAction instead.
        /// </summary>
        /// <param name="output"></param>
        /// <param name="s1"></param>
        /// <param name="s2"></param>
        /// <param name="s3"></param>
        public static void IterLink(StringBuilder output, string s1, string s2, string s3)
        {
            LinkContainer lc = new LinkContainer(output.ToString());
            Globals.linkContainer.Add(lc.counter, lc);
