    //A container for spreadsheet-like cells, using structs for speed.
    public struct CellLight
    {
        public double data;
        public string text;
        public DateTime dateTime;
        public ECellLightType type;
        public bool hasQuotes;
        public DName name = null;

        public CellLight(double input)
        {
            text = null;
            data = input;
            dateTime = DateTime.MinValue;
            type = ECellLightType.Double;
            hasQuotes = false;
            name = null;
        }

        public CellLight(DateTime input)
        {
            text = null;
            data = double.NaN;
            dateTime = input;
            type = ECellLightType.DateTime;
            hasQuotes = false;
            name = null;
        }

        public CellLight(string input)
        {            
            text = input;
            data = double.NaN;
            dateTime = DateTime.MinValue;
            type = ECellLightType.String;
            hasQuotes = false;
            name = null;
        }

        public CellLight(string input, bool hasQuotes2)
        {
            text = input;
            data = double.NaN;
            dateTime = DateTime.MinValue;
            type = ECellLightType.String;
            hasQuotes = hasQuotes2;
            name = null;
        }

        public CellLight(DName input)
        {
            text = null;
            data = double.NaN;
            dateTime = DateTime.MinValue;
            type = ECellLightType.DName;
            hasQuotes = false;
            name = input;
        }

        public string ToString()
        {
            string rv = "---null---";
            if (this.type == ECellLightType.DateTime)
            {
                rv = "a date";
            }
            else if (this.type == ECellLightType.Double)
            {
                rv = this.data.ToString();
            }
            else if (this.type == ECellLightType.String)
            {
                rv = this.text;
            }
            return rv;
        }
    }

    public class FrameLightRow
    {
        public List<CellLight> storageDimensions = new List<CellLight>();
        public List<CellLight> storageValues = new List<CellLight>();
        public FrameLight parent = null;

        public void AddDimension(FrameLight frame, string s, CellLight c)
        {
            int i = -12345;
            if (frame.frameDimensionNames.TryGetValue(s, out i))
            {
                this.storageDimensions[i] = c;
            }
            else
            {
                this.storageDimensions.Add(c);
                frame.frameDimensionNames.Add(s, this.storageDimensions.Count - 1);
            }            
        }

        public void AddValue(FrameLight frame, string s, CellLight c)
        {
            int i = -12345;
            if (frame.frameValueNames.TryGetValue(s, out i))
            {
                this.storageValues[i] = c;
            }
            else
            {
                this.storageValues.Add(c);
                frame.frameValueNames.Add(s, this.storageValues.Count - 1);
            }
        }

        /// <summary>
        /// No test that it exists, may create exception.
        /// </summary>
        /// <param name="frame"></param>
        /// <param name="s"></param>
        /// <returns></returns>
        public CellLight GetDimension(FrameLight frame, string s)
        {
            int i = -12345;
            frame.frameDimensionNames.TryGetValue(s, out i);
            CellLight c = this.storageDimensions[i];
            return c;
        }

        /// <summary>
        /// No test that it exists, may create exception.
        /// </summary>
        /// <param name="frame"></param>
        /// <param name="s"></param>
        /// <returns></returns>
        public CellLight GetValue(FrameLight frame, string s)
        {
            int i = -12345;
            frame.frameValueNames.TryGetValue(s, out i);
            CellLight c = this.storageValues[i];
            return c;
        }

        public FrameLightRow()
        {
            this.storageDimensions = new List<CellLight>();
            this.storageValues = new List<CellLight>();
        }

        public FrameLightRow(FrameLight frame)
        {            
            this.storageDimensions = new List<CellLight>();
            this.storageValues = new List<CellLight>();
            for (int i = 0; i < frame.frameDimensionNames.Count; i++) storageDimensions.Add(new CellLight()); //null cell placeholder
            for (int i = 0; i < frame.frameValueNames.Count; i++) storageValues.Add(new CellLight()); //null cell placeholder
            this.parent = frame;
        }

        public FrameLightRow(FrameLight_OLD frame)
        {
            this.storageDimensions = new List<CellLight>(new CellLight[frame.frameColNames.Count]); //fills it with "null"-objects  t);            
        }

        public void Set(FrameLight_OLD frame, string colname, CellLight cell)
        {
            int i = FindColumn(frame, colname);
            this.storageDimensions[i] = cell;
        }

        public CellLight Get(FrameLight_OLD frame, string colname)
        {
            int i = FindColumn(frame, colname);
            return this.storageDimensions[i];
        }

        public static bool HasColumn(FrameLight_OLD frame, string colname)
        {
            for (int i = 0; i < frame.frameColNames.Count; i++)
            {
                if (G.Equal(frame.frameColNames[i], colname)) return true;
            }
            return false;
        }

        public static int FindColumn(FrameLight_OLD frame, string colname)
        {
            int j = -12345;
            for (int i = 0; i < frame.frameColNames.Count; i++)
            {
                if (G.Equal(frame.frameColNames[i], colname)) j = i;
            }
            if (j == -12345)
            {
                new Error("Could not find name '" + colname + "'");
            }
            return j;
        }
    }

