    /// <summary>
    /// Wrapper for dictionaries, used for instance in GAMS scalar model, with type T values. 
    /// For variables like x[a, b] the issue is that x[a,b] should be equal (note missing blank).
    /// But GekkoDictionaryBlanks can be used for other things as well.
    /// Beware of method GetInt() instead of Get() that for int type returns -12345 if not found as key.
    /// The keys will be squeezed (blanks removed, except if inside '...' quotes), so the info on these blanks is not
    /// preserved (but the letter case is). Use GetKeys() to get the keys out, with nice blanks after commas!
    /// </summary>
    [ProtoContract]
    public class GekkoDictionaryBlanks<T>
    {
        [ProtoMember(1)]
        private GekkoDictionary<string, T> storage = new GekkoDictionary<string, T>(StringComparer.OrdinalIgnoreCase);

        public List<string> GetKeys()
        {
            List<string> m = this.storage.Keys.ToList();
            List<string> m2 = new List<string>();
            foreach (string s in m)
            {
                m2.Add(G.HandleBlanksResurrect(s));
            }
            return m2;
        }        

        /// <summary>
        /// Add something. Beware: case-insensitive keys. The input string may contain blanks,
        /// which will be removed before add ("x[a, b]" becomes "x[a,b]").
        /// </summary>
        /// <param name="s"></param>
        /// <param name="i"></param>
        public void Add(string s, T i, bool willRemoveBlanks)
        {
            if (willRemoveBlanks) this.storage.Add(G.HandleBlanksRemove(s), i);
            else this.storage.Add(s, i);
        }

        /// <summary>
        /// Overload.
        /// </summary>
        /// <param name="s"></param>
        /// <param name="i"></param>
        public void Add(string s, T i)
        {
            Add(s, i, true);
        }

        /// <summary>
        /// Add something, if it is not already present. Beware: case-insensitive keys. The input string may contain blanks,
        /// which will be removed before add ("x[a, b]" becomes "x[a,b]").
        /// </summary>
        /// <param name="s"></param>
        /// <param name="i"></param>
        /// <param name="willRemoveBlanks"></param>
        public void AddIfNotAlreadyThere(string s, T i, bool willRemoveBlanks)
        {            
            string s2 = null;
            if (willRemoveBlanks) s2 = G.HandleBlanksRemove(s);
            else s2 = s;
            if (!this.storage.ContainsKey(s2))
            {
                this.storage.Add(s2, i);
            }
        }

        public void AddIfNotAlreadyThere(string s, T i)
        {
            AddIfNotAlreadyThere(s, i, true);
        }

        /// <summary>
        /// See if s is in dictionary. Beware: case-insensitive keys. The input string may contain blanks,
        /// which will be removed ("x[a, b]" becomes "x[a,b]"). For objects returns null if not found.
        /// But BEWARE that for for instance int type, 0 will be returned if string is not found. If
        /// this is a problem, use GetInt()!!
        /// </summary>
        /// <param name="s"></param>
        /// <returns></returns>
        public T Get(string s, bool willRemoveBlanks)
        {
            string s2 = null;
            if (willRemoveBlanks) s2 = G.HandleBlanksRemove(s);
            else s2 = s;
            T i; bool b = this.storage.TryGetValue(s2, out i);
            if (!b)
            {
                i = default(T);
            }
            return i;
        }

        /// <summary>
        /// See if s is in dictionary. Beware: case-insensitive keys. The input string may contain blanks,
        /// which will be removed ("x[a, b]" becomes "x[a,b]").
        /// Note: if key is not found, the method returns -12345. The normal Get() returns 0, so this method
        /// may be better in some cases (where a value = 0 makes sense).
        /// </summary>
        /// <param name="s"></param>
        /// <param name="willRemoveBlanks"></param>
        /// <returns></returns>
        public int GetInt(string s, bool willRemoveBlanks)
        {
            string s2 = null;
            if (willRemoveBlanks) s2 = G.HandleBlanksRemove(s);
            else s2 = s;
            T i; bool b = this.storage.TryGetValue(s2, out i);
            if (!b)
            {
                return -12345;
            }
            return (int)(i as int?); //second parenthesis will be <> null if the key type is int. Hmm boxing speed penalty, but only when the key is actually found, so probably ok.
        }

        /// <summary>
        /// Overload, removes blanks from input string.
        /// </summary>
        /// <param name="s"></param>
        /// <returns></returns>
        public T Get(string s)
        {
            return Get(s, true);
        }

        /// <summary>
        /// Overload, removes blanks from input string.
        /// </summary>
        /// <param name="s"></param>
        /// <returns></returns>
        public int GetInt(string s)
        {
            return GetInt(s, true);
        }

        //Does the dict contain the key?
        public bool ContainsKey(string s, bool willRemoveBlanks)
        {
            string s2 = null;
            if (willRemoveBlanks) s2 = G.HandleBlanksRemove(s);
            else s2 = s;
            bool b = this.storage.ContainsKey(s2);
            return b;
        }

        //Overload
        public bool ContainsKey(string s)
        {
            return ContainsKey(s, true);
        }

        public int Count()
        {
            return this.storage.Count;
        }
        
        /// <summary>
        /// Only intended to be used when iterating!
        /// </summary>
        /// <returns></returns>
        public GekkoDictionary<string, T> GetDictionaryForIteration()
        {
            return this.storage;
        }
    }

    /// <summary>
    /// Dictionary where the string keys are case-independent.
    /// If there are varying blanks (and commas) inside the keys, consider GekkoDictionaryBlanks.
    /// </summary>
    /// <typeparam name="TKey"></typeparam>
    /// <typeparam name="TValue"></typeparam>
    public class GekkoDictionary<TKey, TValue> : Dictionary<TKey, TValue>
    {
        public GekkoDictionary()
            : base()
        {
            if (typeof(TKey) == typeof(string))
            {
                //string keys should be called with ignorecase
                new Error("Technical error 437834873");
            }
        }
        //public GekkoDictionary(int capacity) : base(capacity) { }  //not used
        public GekkoDictionary(IEqualityComparer<TKey> comparer)
            : base(comparer)
        {
            if (typeof(TKey) == typeof(string))
            {
                if (comparer != StringComparer.OrdinalIgnoreCase)
                {
                    //string keys should be called with ignorecase
                    new Error("Technical error 437834874");
                }
            }
        }

        //Would be nice to be able override the indexer, but this does not seem possible...
        //Anyway, nice to have a special wrapper for Dictionaries
    }

